import{_ as d,o as a,c as e,a3 as r}from"./chunks/framework.BlfGB29P.js";const b=JSON.parse('{"title":"数据与权限设计","description":"为售后执行 Agent 填写本项目数据流、租户边界、保留与删除策略；方法外链多租户与记忆隔离，本文交付可落地的项目表。","frontmatter":{"title":"数据与权限设计","description":"为售后执行 Agent 填写本项目数据流、租户边界、保留与删除策略；方法外链多租户与记忆隔离，本文交付可落地的项目表。","outline":[2,3],"article":{"type":"project","structure":"project"}},"headers":[],"relativePath":"ts-ai/architecture/delivery/data-permission-design.md","filePath":"ts-ai/architecture/delivery/data-permission-design.md","lastUpdated":1786113687000}'),n={name:"ts-ai/architecture/delivery/data-permission-design.md"};function s(o,t,h,i,l,c){return a(),e("div",null,[...t[0]||(t[0]=[r(`<h1 id="数据与权限设计" tabindex="-1">数据与权限设计 <a class="header-anchor" href="#数据与权限设计" aria-label="Permalink to &quot;数据与权限设计&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本篇填写<strong>本项目</strong>的数据流、存储所有权、租户边界与保留/删除规则。隔离机制见 <a href="/ts-ai/quality/security-governance/multi-tenancy-isolation">多租户隔离</a>、<a href="/ts-ai/knowledge/memory/tenant-permission-isolation">记忆租户</a>；表模型细节见服务端数据任务相关章，此处不重讲 ORM。</p><p>填写样例：<strong>售后执行 Agent（含审批）</strong>（虚构样例项目，仅演示填写格式；实际交付项目见 <a href="/ts-ai/architecture/ai-customer-support/">实战 · AI 客服中心</a>）。</p><h2 id="_1-范围与身份" tabindex="-1">1. 范围与身份 <a class="header-anchor" href="#_1-范围与身份" aria-label="Permalink to &quot;1. 范围与身份&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填写值（售后）</th></tr></thead><tbody><tr><td>项目代号</td><td><code>aftersales-graph-v1</code></td></tr><tr><td>数据分级</td><td>订单/用户联系方式 = 机密；政策条文 = 内部；模型日志 = 内部（脱敏）</td></tr><tr><td>租户模型</td><td>硬隔离：<code>tenant_id</code> 强制谓词；禁止跨租户联表</td></tr><tr><td>主体</td><td>终端用户、坐席、审批人、租户管理员、平台审计</td></tr><tr><td>法务锚点</td><td>工单与聊天保留 180 天；删除请求 15 个工作日内完成</td></tr><tr><td>文档版本</td><td><code>data-perm@2026-08-09</code>；随 <code>api@1.8.x</code></td></tr></tbody></table><h2 id="_2-数据流" tabindex="-1">2. 数据流 <a class="header-anchor" href="#_2-数据流" aria-label="Permalink to &quot;2. 数据流&quot;">​</a></h2><h3 id="_2-1-端到端流-本项目" tabindex="-1">2.1 端到端流（本项目） <a class="header-anchor" href="#_2-1-端到端流-本项目" aria-label="Permalink to &quot;2.1 端到端流（本项目）&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户/坐席请求</span></span>
<span class="line"><span>  → API（鉴权，注入 tenantId/userId/roles）</span></span>
<span class="line"><span>  → Agent/Graph（只读工具：订单、政策；写工具：退款建议、创建审批）</span></span>
<span class="line"><span>  → 确认后执行器（幂等键 + 业务校验）</span></span>
<span class="line"><span>  → PostgreSQL（Thread/Run/Message/Approval）</span></span>
<span class="line"><span>  → Redis（短态：锁、限流、confirmation nonce）</span></span>
<span class="line"><span>  → 对象存储（附件，预签名，租户前缀）</span></span>
<span class="line"><span>  → 审计日志（不可变，脱敏）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>模型供应商仅接收<strong>最小化</strong>消息与工具结果摘要；禁止上传整库导出或未脱敏身份证照片 OCR 全文（V1 附件只存元数据 + 病毒扫描状态）。</p><h3 id="_2-2-数据对象清单" tabindex="-1">2.2 数据对象清单 <a class="header-anchor" href="#_2-2-数据对象清单" aria-label="Permalink to &quot;2.2 数据对象清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对象</th><th>存储</th><th>所有者服务</th><th>含 PII</th><th>跨租户</th></tr></thead><tbody><tr><td><code>threads</code> / <code>messages</code></td><td>PostgreSQL</td><td>AI API</td><td>可能</td><td>否</td></tr><tr><td><code>runs</code> / <code>checkpoints</code></td><td>PostgreSQL + 可选对象</td><td>AI Worker</td><td>间接</td><td>否</td></tr><tr><td><code>approvals</code></td><td>PostgreSQL</td><td>Workflow</td><td>是（金额、用户）</td><td>否</td></tr><tr><td><code>tool_audit</code></td><td>PostgreSQL</td><td>AI API</td><td>摘要</td><td>否</td></tr><tr><td><code>order_snapshot</code></td><td>缓存列 / 外部 OMS</td><td>OMS 只读 API</td><td>是</td><td>否</td></tr><tr><td><code>policy_chunks</code></td><td>向量库 + PG</td><td>KB 索引 Job</td><td>否</td><td>按租户索引</td></tr><tr><td><code>attachments</code></td><td>S3 前缀 <code>t/{tenantId}/…</code></td><td>Files</td><td>是</td><td>否</td></tr><tr><td><code>redis:confirm:*</code></td><td>Redis TTL 15m</td><td>API</td><td>否（仅 ID）</td><td>key 含 tenant</td></tr><tr><td><code>privacy_requests</code></td><td>PostgreSQL</td><td>Privacy Job</td><td>是</td><td>否</td></tr></tbody></table><h3 id="_2-3-写入与读取路径" tabindex="-1">2.3 写入与读取路径 <a class="header-anchor" href="#_2-3-写入与读取路径" aria-label="Permalink to &quot;2.3 写入与读取路径&quot;">​</a></h3><table tabindex="0"><thead><tr><th>动作</th><th>谁写</th><th>谁读</th><th>校验</th></tr></thead><tbody><tr><td>创建 Thread</td><td>登录用户</td><td>同用户或被分配坐席</td><td><code>tenant_id</code> + <code>user_id</code></td></tr><tr><td>追加 Message</td><td>API（用户/助手/工具）</td><td>同 Thread 授权主体</td><td>Run 归属校验</td></tr><tr><td>创建 Approval</td><td>Graph 节点（确认后）</td><td>审批人角色</td><td>金额阈值 + 角色</td></tr><tr><td>执行退款工具</td><td>Executor</td><td>OMS</td><td>幂等键 <code>approvalId</code>；双检状态</td></tr><tr><td>检索政策</td><td>Retriever</td><td>Agent</td><td>索引 <code>tenant_id</code> 过滤</td></tr><tr><td>导出审计</td><td>平台审计角色</td><td>安全/合规</td><td>工单制；结果脱敏</td></tr></tbody></table><h2 id="_3-租户与权限" tabindex="-1">3. 租户与权限 <a class="header-anchor" href="#_3-租户与权限" aria-label="Permalink to &quot;3. 租户与权限&quot;">​</a></h2><h3 id="_3-1-角色-×-资源矩阵-已填" tabindex="-1">3.1 角色 × 资源矩阵（已填） <a class="header-anchor" href="#_3-1-角色-×-资源矩阵-已填" aria-label="Permalink to &quot;3.1 角色 × 资源矩阵（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>资源</th><th>终端用户</th><th>坐席</th><th>审批人</th><th>租户管理员</th><th>平台运维</th></tr></thead><tbody><tr><td>本人工单 Thread</td><td>RW</td><td>R（分配后 RW）</td><td>R（关联审批）</td><td>R（元数据）</td><td>无默认 R</td></tr><tr><td>他人工单</td><td>—</td><td>仅队列内</td><td>—</td><td>元数据统计</td><td>—</td></tr><tr><td>退款执行</td><td>确认发起</td><td>建议</td><td>批准/驳回</td><td>配置阈值</td><td>熔断开关</td></tr><tr><td>政策索引</td><td>经助手读</td><td>经助手读</td><td>经助手读</td><td>管理文档</td><td>运维索引 Job</td></tr><tr><td>Secret / Key</td><td>—</td><td>—</td><td>—</td><td>—</td><td>保险库角色</td></tr><tr><td>原始模型日志</td><td>—</td><td>—</td><td>—</td><td>—</td><td>脱敏只读</td></tr></tbody></table><p>「—」表示默认拒绝。实现上每个查询带 <code>tenant_id</code>；服务端拒绝客户端自报租户。</p><h3 id="_3-2-工具权限" tabindex="-1">3.2 工具权限 <a class="header-anchor" href="#_3-2-工具权限" aria-label="Permalink to &quot;3.2 工具权限&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>风险</th><th>前置</th><th>确认</th></tr></thead><tbody><tr><td><code>get_order</code></td><td>L1</td><td>订单属于当前用户或坐席工单</td><td>否</td></tr><tr><td><code>search_policy</code></td><td>L1</td><td>租户索引</td><td>否</td></tr><tr><td><code>draft_refund</code></td><td>L2</td><td>有订单快照</td><td>否（只草稿）</td></tr><tr><td><code>create_approval</code></td><td>L2</td><td>草稿完整</td><td>是（用户/坐席）</td></tr><tr><td><code>execute_refund</code></td><td>L3</td><td>审批通过 + 未执行</td><td>是（系统二次校验，非聊天空确认）</td></tr></tbody></table><h3 id="_3-3-金额阈值-本项目" tabindex="-1">3.3 金额阈值（本项目） <a class="header-anchor" href="#_3-3-金额阈值-本项目" aria-label="Permalink to &quot;3.3 金额阈值（本项目）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>金额（单笔）</th><th>自动化</th><th>审批</th></tr></thead><tbody><tr><td>≤ ¥50</td><td>可自动建议；仍需用户确认创建</td><td>无需二级</td></tr><tr><td>¥50–¥500</td><td>必须审批人</td><td>单人</td></tr><tr><td>&gt; ¥500</td><td>必须审批人</td><td>双人（主管 + 财务）</td></tr></tbody></table><p>阈值配置属租户管理员可写；变更进审计。</p><h3 id="_3-4-越权测试样例-必须保留" tabindex="-1">3.4 越权测试样例（必须保留） <a class="header-anchor" href="#_3-4-越权测试样例-必须保留" aria-label="Permalink to &quot;3.4 越权测试样例（必须保留）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>步骤</th><th>期望</th></tr></thead><tbody><tr><td>P1</td><td>用户 A 的 Token 读 Thread B</td><td>404/403</td></tr><tr><td>P2</td><td>篡改 body <code>tenantId</code> 为其他租户</td><td>忽略 body，以 Token 为准；或 400</td></tr><tr><td>P3</td><td>审批人批准非本租户 approval</td><td>403；无 OMS 调用</td></tr><tr><td>P4</td><td>向量查询不带租户过滤（人为关掉）</td><td>集成测试失败（守门）</td></tr><tr><td>P5</td><td>坐席读未分配队列外 Thread</td><td>403</td></tr><tr><td>P6</td><td>重放已消费确认 nonce 执行退款</td><td>409；OMS 无第二笔</td></tr></tbody></table><h2 id="_4-保留、删除与出境" tabindex="-1">4. 保留、删除与出境 <a class="header-anchor" href="#_4-保留、删除与出境" aria-label="Permalink to &quot;4. 保留、删除与出境&quot;">​</a></h2><h3 id="_4-1-保留策略-已填" tabindex="-1">4.1 保留策略（已填） <a class="header-anchor" href="#_4-1-保留策略-已填" aria-label="Permalink to &quot;4.1 保留策略（已填）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>数据类</th><th>在线保留</th><th>归档</th><th>备注</th></tr></thead><tbody><tr><td>消息 / Run</td><td>180 天</td><td>冷存 1 年哈希索引</td><td>超时任务周批</td></tr><tr><td>Approval</td><td>180 天</td><td>与财务对账期对齐 2 年元数据</td><td>金额字段加密列</td></tr><tr><td>Checkpoint</td><td>30 天</td><td>不归档</td><td>过期删除</td></tr><tr><td>Redis 确认 nonce</td><td>TTL 15m</td><td>无</td><td>—</td></tr><tr><td>附件</td><td>90 天</td><td>用户可提前删</td><td>删对象 + 断链</td></tr><tr><td>审计日志</td><td>2 年</td><td>只追加</td><td>不可业务删除</td></tr></tbody></table><h3 id="_4-2-删除与主体请求" tabindex="-1">4.2 删除与主体请求 <a class="header-anchor" href="#_4-2-删除与主体请求" aria-label="Permalink to &quot;4.2 删除与主体请求&quot;">​</a></h3><table tabindex="0"><thead><tr><th>请求类型</th><th>SLA</th><th>动作</th></tr></thead><tbody><tr><td>用户删除会话</td><td>24h</td><td>软删 → 7 日后硬删消息；审计留存「已删」事件</td></tr><tr><td>账户注销</td><td>15 工作日</td><td>匿名化 PII；订单号哈希；保留财务必要字段</td></tr><tr><td>租户退租</td><td>合同+30 天</td><td>导出包 → 销毁索引与对象前缀 → 双人复核</td></tr></tbody></table><p>删除 Job 幂等；报告写入 <code>privacy_requests</code>（<code>received</code> / <code>done</code> / <code>partial</code>）。</p><h3 id="_4-3-出境与供应商" tabindex="-1">4.3 出境与供应商 <a class="header-anchor" href="#_4-3-出境与供应商" aria-label="Permalink to &quot;4.3 出境与供应商&quot;">​</a></h3><table tabindex="0"><thead><tr><th>流向</th><th>是否出境</th><th>控制</th></tr></thead><tbody><tr><td>模型 API</td><td>按供应商区域配置（本项目：国内节点）</td><td>合同 + 数据清单；禁止发身份证号</td></tr><tr><td>对象存储</td><td>同区域</td><td>桶策略拒公有</td></tr><tr><td>可观测平台</td><td>Trace 默认脱敏 body</td><td>采样；PII 字段红线</td></tr></tbody></table><h2 id="_5-字段与加密-本项目要点" tabindex="-1">5. 字段与加密（本项目要点） <a class="header-anchor" href="#_5-字段与加密-本项目要点" aria-label="Permalink to &quot;5. 字段与加密（本项目要点）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>表/集合</th><th>敏感字段</th><th>保护</th><th>备注</th></tr></thead><tbody><tr><td><code>messages.content</code></td><td>用户原文</td><td>传输 TLS；磁盘默认加密卷</td><td>日志禁止整段打印</td></tr><tr><td><code>approvals.amount_cents</code></td><td>金额</td><td>应用层加密列 + 审计明文仅财务角色</td><td>解密走 KMS 角色</td></tr><tr><td><code>approvals.customer_phone</code></td><td>手机号</td><td>加密；展示掩码</td><td>坐席默认掩码</td></tr><tr><td><code>tool_audit.request_json</code></td><td>可能含订单</td><td>存 redacted 摘要</td><td>全量仅安全工单</td></tr><tr><td><code>attachments</code> 对象</td><td>图片/PDF</td><td>私有桶；预签名 10min</td><td>病毒扫描后可读</td></tr></tbody></table><p>索引：<code>threads (tenant_id, user_id, updated_at)</code>；<code>approvals (tenant_id, status, created_at)</code>。所有业务查询<strong>第一谓词</strong>为 <code>tenant_id = :tokenTenant</code>。</p><h2 id="_6-一次访问裁决轨迹-样例" tabindex="-1">6. 一次访问裁决轨迹（样例） <a class="header-anchor" href="#_6-一次访问裁决轨迹-样例" aria-label="Permalink to &quot;6. 一次访问裁决轨迹（样例）&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请求: GET /threads/th_B</span></span>
<span class="line"><span>Authorization: Bearer (tenant=t_a, user=u_1)</span></span>
<span class="line"><span>→ 解析主体: tenant=t_a, user=u_1</span></span>
<span class="line"><span>→ 加载 Thread th_B: tenant=t_b</span></span>
<span class="line"><span>→ 裁决: deny (tenant_mismatch)</span></span>
<span class="line"><span>→ 响应: 404</span></span>
<span class="line"><span>→ 审计: authz_deny reason=tenant_mismatch</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>前端不得依赖「有 ID 就能打开」；预发用 P1–P6 每晚回归。</p><h2 id="_7-备份与运维读路径" tabindex="-1">7. 备份与运维读路径 <a class="header-anchor" href="#_7-备份与运维读路径" aria-label="Permalink to &quot;7. 备份与运维读路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>路径</th><th>谁</th><th>控制</th></tr></thead><tbody><tr><td>逻辑备份还原到演练库</td><td>运维</td><td>演练库脱敏脚本强制跑完才开 VPN</td></tr><tr><td>只读 SQL 排障</td><td>工程 on-call</td><td>工单号；<code>approvalId</code> 级查询；禁无租户扫表</td></tr><tr><td>对象存储列举</td><td>平台存储角色</td><td>前缀必须含 <code>t/{tenantId}/</code></td></tr><tr><td>紧急导出给监管</td><td>合规</td><td>双人；水印；到期回收</td></tr></tbody></table><h2 id="_8-与相邻交付的接口" tabindex="-1">8. 与相邻交付的接口 <a class="header-anchor" href="#_8-与相邻交付的接口" aria-label="Permalink to &quot;8. 与相邻交付的接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>交付物</th><th>本设计提供的输入</th></tr></thead><tbody><tr><td><a href="/ts-ai/architecture/delivery/requirements-acceptance">需求与验收</a></td><td>权限边界与非目标对齐</td></tr><tr><td><a href="/ts-ai/architecture/delivery/threat-model">威胁模型</a></td><td>资产表、数据流、越权路径</td></tr><tr><td><a href="/ts-ai/architecture/delivery/evaluation-plan">评测方案</a></td><td><code>security</code> 子集用 P1–P6</td></tr><tr><td><a href="/ts-ai/architecture/delivery/operations-handover">运维交接</a></td><td>删除 Job、保留批次值班说明</td></tr></tbody></table><h2 id="_9-开放问题与决策" tabindex="-1">9. 开放问题与决策 <a class="header-anchor" href="#_9-开放问题与决策" aria-label="Permalink to &quot;9. 开放问题与决策&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>决策</th><th>日期</th></tr></thead><tbody><tr><td>坐席是否可导出全程聊天</td><td>V1 否；仅工单摘要</td><td>2026-08-08</td></tr><tr><td>向量库物理隔离 vs 逻辑过滤</td><td>V1 逻辑过滤 + 强制测试；大客户可独立索引</td><td>2026-08-08</td></tr><tr><td>模型日志是否含工具原始 JSON</td><td>否；仅摘要字段</td><td>2026-08-09</td></tr></tbody></table><h2 id="_10-签字" tabindex="-1">10. 签字 <a class="header-anchor" href="#_10-签字" aria-label="Permalink to &quot;10. 签字&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>确认</th><th>日期</th></tr></thead><tbody><tr><td>工程</td><td>表/索引/强制谓词已落地</td><td>2026-08-08</td></tr><tr><td>安全</td><td>矩阵与越权样例充分</td><td>2026-08-08</td></tr><tr><td>数据/隐私</td><td>保留与删除 SLA 可执行</td><td>2026-08-09</td></tr><tr><td>产品</td><td>坐席/审批可见范围符合业务</td><td>2026-08-09</td></tr></tbody></table><h2 id="_11-变更日志" tabindex="-1">11. 变更日志 <a class="header-anchor" href="#_11-变更日志" aria-label="Permalink to &quot;11. 变更日志&quot;">​</a></h2><table tabindex="0"><thead><tr><th>日期</th><th>变更</th><th>作者</th></tr></thead><tbody><tr><td>2026-08-01</td><td>初稿：对象清单与角色矩阵</td><td>赵衡</td></tr><tr><td>2026-08-08</td><td>加入金额阈值与 P5/P6</td><td>陈安</td></tr><tr><td>2026-08-09</td><td>保留天数与隐私 SLA 定稿</td><td>隐私对接人</td></tr></tbody></table><p>读者若改做<strong>流式工作台</strong>，删除审批/退款对象，保留 Thread/Run/限流与确认 nonce；若改做<strong>知识库</strong>，强化 <code>policy_chunks</code> 租户索引与引用审计，弱化 OMS。</p><h2 id="_12-自检清单" tabindex="-1">12. 自检清单 <a class="header-anchor" href="#_12-自检清单" aria-label="Permalink to &quot;12. 自检清单&quot;">​</a></h2><ul><li>[x] 数据流从入口到审计一条线，无「神秘旁路写库」</li><li>[x] 对象清单含存储、PII、跨租户三列</li><li>[x] 角色矩阵与金额阈值已填</li><li>[x] 高风险工具确认与执行分离</li><li>[x] 保留/删除/出境有具体天数与 SLA</li><li>[x] 敏感字段与备份读路径已登记</li><li>[x] 方法外链 quality，未重抄隔离实现全文</li></ul>`,52)])])}const u=d(n,[["render",s]]);export{b as __pageData,u as default};
